import Foundation
#if canImport(XCTest)
import XCTest
#endif
@testable import SnowCore
final class StickerStudioTests:XCTestCase {
 func testCatalogueHasTwentyUniqueAssetsAndValidPivots(){XCTAssertEqual(StickerAsset.all.count,20);XCTAssertEqual(Set(StickerAsset.all.map(\.id)).count,20);for a in StickerAsset.all {XCTAssertTrue(a.width>0 && a.height>0);XCTAssertTrue(a.pivot.x>=0 && a.pivot.x<=1 && a.pivot.y>=0 && a.pivot.y<=1)}}
 func testTransformValidationAndSafeText(){var item=StudioSticker(assetID:"sticker_sign",anchor:StickerAnchor(screen:"1",local:Vec(.infinity,.nan)));item.scale = .nan;item.rotation = .infinity;item.segments=999;item.text="Merry\nChristmas\u{0000}"+String(repeating:"!",count:40);item.validate();XCTAssertEqual(item.scale,1);XCTAssertEqual(item.rotation,0);XCTAssertEqual(item.segments,1);XCTAssertEqual(item.text.count,24);XCTAssertFalse(item.text.contains("\n"));XCTAssertEqual(item.anchor.local,Vec(0.5,0.5))}
 func testUndoRedoBranchAndBound(){var history=StickerHistory(),s=StickerStudioSettings();for i in 0..<80 {let old=s;s.defaultSize=Double(i);history.record(old,s)};XCTAssertEqual(history.undoStack.count,60);let previous=history.undo(s)!;XCTAssertEqual(previous.defaultSize,78);XCTAssertEqual(history.redo(previous),s);let old=s;s.hidden=true;history.record(old,s);XCTAssertTrue(history.redoStack.isEmpty)}
 func testWindowAttachmentTracksResize(){let a=Vec(0.97,0.04);XCTAssertEqual(StickerGeometry.windowPoint(a,frame:Rect(10,20,500,400)),Vec(495,36));XCTAssertEqual(StickerGeometry.windowPoint(a,frame:Rect(-100,100,1000,500)),Vec(870,120))}
 func testOcclusionSubtractsForegroundWindows(){let pieces=StickerGeometry.visiblePieces(Rect(0,0,100,100),blocking:[Rect(50,0,50,100)]);XCTAssertEqual(pieces.reduce(0){$0+$1.width*$1.height},5000);XCTAssertTrue(StickerGeometry.visiblePieces(Rect(0,0,100,100),blocking:[Rect(-1,-1,102,102)]).isEmpty)}
 func testDesktopClampingOnNegativeScreenCoordinates(){let p=StickerGeometry.desktopPoint(Vec(2,-1),frame:Rect(-1920,0,1920,1080),margin:40);XCTAssertEqual(p,Vec(-40,72))}
 func testPresetDedupesCyclesAndDoesNotLoseItemsOnQualityChange(){var s=StickerStudioSettings();let a=StudioSticker(assetID:"sticker_bow",anchor:StickerAnchor(kind:.decoration,screen:"1",local:Vec(),parent:"b"),id:"a"),b=StudioSticker(assetID:"sticker_bow",anchor:StickerAnchor(kind:.decoration,screen:"1",local:Vec(),parent:"a"),id:"b");s.items=[a,b,a];s.validate();XCTAssertEqual(s.items.count,2);XCTAssertFalse(s.items[0].visible);s.items=(0..<100).map{StudioSticker(assetID:"sticker_star",anchor:StickerAnchor(screen:"1",local:Vec()),id:String($0))};s.quality="low";s.validate();XCTAssertEqual(s.items.count,100);XCTAssertEqual(s.limit,40)}
 func testOldConfigurationAndIdentityRoundTrip() throws {var legacy=try JSONSerialization.jsonObject(with:JSONEncoder().encode(Configuration())) as! [String:Any];legacy.removeValue(forKey:"stickers");var config=try Configuration.decodeCompatible(JSONSerialization.data(withJSONObject:legacy));XCTAssertTrue(config.stickers.items.isEmpty);var p=Placement(tree:Vec(0.5,0.9));p.treeIdentity=UUID().uuidString;config.placements["1"]=p;config.stickers.items=[StudioSticker(assetID:"sticker_hat",anchor:StickerAnchor(kind:.snowman,screen:"1",local:Vec(0.5,0.1),parent:UUID().uuidString))];config.validate();let copy=try Configuration.decodeCompatible(JSONEncoder().encode(config));XCTAssertEqual(copy,config);XCTAssertEqual(copy.placements["1"]?.treeIdentity,p.treeIdentity)}
}
